begin;
select no_plan();
\ir ../support/academic-fixture.psql
select has_function('public','get_snapshot_export',array['jsonb','uuid','uuid'],'audited snapshot export exists');
insert into auth.users(id,email,aud,role) values(pg_temp.fixture('cam'),'cam-export@example.invalid','authenticated','authenticated');
insert into public.contas_demo(ator_id,rotulo) select pg_temp.fixture(who),who from unnest(array['actor','reviewer','cam'])who;
insert into public.competencias(id,codigo,referencia,estado,modelo) values(pg_temp.fixture('export-cycle'),'EXPORT-2026-10','2026-10-01','aberta',2);
insert into public.escopos(id,codigo,tipo) select pg_temp.fixture('export-scope-'||n),'EXPORT-'||n,case when n=1 then 'distrito' else 'unidade' end from generate_series(1,4)n;
insert into public.territorios_competencia(competencia_id,unidade_id,distrito_id) select pg_temp.fixture('export-cycle'),pg_temp.fixture('export-scope-'||n),pg_temp.fixture('export-scope-1') from generate_series(2,4)n;
insert into public.posicoes_esperadas(id,competencia_id,indicador_id,alvo_id,regra_id,aplicavel,informante_id,revisor_id) select pg_temp.fixture('export-pos-'||n),pg_temp.fixture('export-cycle'),'c0de0000-0000-4000-8000-000000000002',pg_temp.fixture('export-scope-'||n),'c0de0000-0000-4000-8000-000000000004',n<>4,pg_temp.fixture('actor'),pg_temp.fixture('reviewer') from generate_series(1,4)n;
insert into public.vinculos(actor_id,papel,escopo_id,indicador_id,vigencia_inicio) select pg_temp.fixture(who),role,pg_temp.fixture('export-scope-'||n),'c0de0000-0000-4000-8000-000000000002',current_date-1 from generate_series(1,4)n cross join(values('actor','area_tecnica'),('reviewer','revisor_tecnico'),('cam','cam'))v(who,role);
create function pg_temp.export_ctx(who text,n integer default 1) returns jsonb language sql security definer as $$select jsonb_build_object('vinculoId',id,'competenciaId',pg_temp.fixture('export-cycle'),'indicadorId',indicador_id) from public.vinculos where actor_id=pg_temp.fixture(who) and escopo_id=pg_temp.fixture('export-scope-'||n);$$;
create function pg_temp.prepare_export_cycle() returns void language plpgsql as $$declare n integer;r jsonb;begin
 for n in 1..3 loop
  perform pg_temp.login_as('actor');r:=public.save_position_draft(pg_temp.export_ctx('actor',n),pg_temp.fixture('export-pos-'||n),1,jsonb_build_object('estadoDado',case when n=3 then 'indisponivel' else 'valor' end,'valor',case when n=3 then null when n=2 then '0' else '10' end,'fonte','Synthetic export source','periodoFonte','2026-10-01','motivo',case when n=3 then 'Synthetic unavailability' else '' end),gen_random_uuid());
  r:=public.submit_position(pg_temp.export_ctx('actor',n),pg_temp.fixture('export-pos-'||n),(r->>'version')::integer,gen_random_uuid());
  perform pg_temp.login_as('reviewer');r:=public.start_position_review(pg_temp.export_ctx('reviewer',n),pg_temp.fixture('export-pos-'||n),(r->>'version')::integer,gen_random_uuid());
  r:=public.review_position(pg_temp.export_ctx('reviewer',n),pg_temp.fixture('export-pos-'||n),(r->>'version')::integer,'accept','Synthetic independent acceptance',gen_random_uuid());
  if n=3 then perform pg_temp.login_as('cam');perform public.decide_unavailability(pg_temp.export_ctx('cam',n),pg_temp.fixture('export-pos-'||n),(r->>'version')::integer,'DEMO-UNAVAILABLE-EXPORT','Synthetic CAM decision',gen_random_uuid());end if;
 end loop;
 perform pg_temp.login_as('cam');
 perform public.transition_cycle(pg_temp.export_ctx('cam'),(public.get_cycle_checklist(pg_temp.export_ctx('cam'))->>'version')::integer,'consolidate','','',gen_random_uuid());
 perform public.transition_cycle(pg_temp.export_ctx('cam'),(public.get_cycle_checklist(pg_temp.export_ctx('cam'))->>'version')::integer,'close','','DEMO-DECISAO-EXPORT',gen_random_uuid());
end;$$;
select pg_temp.login_as('cam');set local role authenticated;
select throws_ok($$select public.get_snapshot_export(pg_temp.export_ctx('cam'),pg_temp.fixture('missing-snapshot'),pg_temp.fixture('export-op'))$$,'55000','invalid_state','open cycle cannot export');
select lives_ok('select pg_temp.prepare_export_cycle()','new snapshot prepared through actual commands');
create temporary table export_saved(bundle jsonb);
insert into export_saved select public.get_snapshot_export(pg_temp.export_ctx('cam'),(public.get_cycle_checklist(pg_temp.export_ctx('cam'))->>'snapshotId')::uuid,pg_temp.fixture('export-op'));
select is((select bundle->>'contractVersion' from export_saved),'1','contract v1');
select is((select bundle->'manifest'->>'publicationVersion' from export_saved),'0','closed unpublished may export');
select is((select bundle->'manifest'->>'positionCount' from export_saved),'4','all four snapshot positions');
select is((select bundle->'manifest'->>'calculableCount' from export_saved),'2','zero is calculable');
select is((select bundle->'manifest'->>'unavailableCount' from export_saved),'1','unavailable counted not zero');
select is((select bundle->'manifest'->>'notApplicableCount' from export_saved),'1','not applicable counted separately');
select is((select bundle->'manifest'->'totals' from export_saved),'[{"tipo":"distrito","unidadeMedida":"pontos sintéticos","sum":"8"},{"tipo":"unidade","unidadeMedida":"pontos sintéticos","sum":"0"}]'::jsonb,'typed totals separated by target type, decimal text');
select is((select bundle->'rows'->1->>'entrada' from export_saved),'0','zero input explicit');
select is((select bundle->'rows'->2->'resultado' from export_saved),'null'::jsonb,'unavailable null result');
select is((select bundle->'rows'->3->'revisao' from export_saved),'null'::jsonb,'not applicable has no fabricated revision');
select is(public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),pg_temp.fixture('export-op')),(select bundle from export_saved),'same operation replays canonical bundle');
select is(public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),gen_random_uuid()),(select bundle from export_saved),'new request same snapshot/version same canonical content');
select throws_ok($$select public.get_snapshot_export(pg_temp.export_ctx('cam'),pg_temp.fixture('missing-snapshot'),pg_temp.fixture('export-op'))$$,'42501','access_denied','foreign snapshot denied before cached data');
select pg_temp.login_as('actor');
select throws_ok($$select public.get_snapshot_export(pg_temp.export_ctx('actor'),(select (bundle->>'snapshotId')::uuid from export_saved),gen_random_uuid())$$,'42501','access_denied','technical user cannot export');
reset role;
select is((select count(*)::integer from public.eventos_auditoria where acao='snapshot_exportado_demo' and recurso_id=pg_temp.fixture('export-cycle')),2,'retry no second event, new request adds event');
select ok(not exists(select 1 from public.eventos_auditoria where acao='snapshot_exportado_demo' and detalhes ?| array['rows','totals','bundle','source','reason']),'audit excludes export content');
update public.escopos set codigo='CHANGED-AFTER-CLOSE' where id=pg_temp.fixture('export-scope-2');
update public.indicadores set codigo='CHANGED-INDICATOR' where id='c0de0000-0000-4000-8000-000000000002';
select pg_temp.login_as('cam');set local role authenticated;
select is(public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),gen_random_uuid()),(select bundle from export_saved),'mutable catalogue cannot change snapshot rows or manifest');
select public.publish_cycle_demo(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),'DEMO-PUBLICACAO-EXPORT',gen_random_uuid());
select is(public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),gen_random_uuid())->'manifest'->>'publicationVersion','1','publication has explicit version 1');
select is(public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),pg_temp.fixture('export-op')),(select bundle from export_saved),'original retry keeps captured publication version');
reset role;
update public.vinculos set ativo=false where actor_id=pg_temp.fixture('cam') and escopo_id=pg_temp.fixture('export-scope-4');
select pg_temp.login_as('cam');set local role authenticated;
select throws_ok($$select public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),pg_temp.fixture('export-op'))$$,'42501','access_denied','revoked coverage denies even cached completed export');
select throws_ok($$select public.get_snapshot_export(pg_temp.export_ctx('cam'),(select (bundle->>'snapshotId')::uuid from export_saved),gen_random_uuid())$$,'42501','access_denied','partial CAM district does not inherit unit coverage');
select throws_ok('select * from public.itens_fechamento','42501',null,'snapshot direct access denied');
reset role;
select ok(not has_function_privilege('anon','public.get_snapshot_export(jsonb,uuid,uuid)','execute'),'anonymous export denied');
select ok(not has_function_privilege('authenticated','private.export_academic_snapshot(jsonb,jsonb,uuid)','execute'),'private export helper denied');
select * from finish();rollback;
